import{_ as t,o,c as r,a2 as l}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"管理后台","description":"","frontmatter":{},"headers":[],"relativePath":"admin/admin-panel.md","filePath":"admin/admin-panel.md","lastUpdated":1785772843000}'),i={name:"admin/admin-panel.md"};function e(n,a,s,d,h,u){return o(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="管理后台" tabindex="-1">管理后台 <a class="header-anchor" href="#管理后台" aria-label="Permalink to &quot;管理后台&quot;">​</a></h1><p>管理后台是 ZViewer 的管理员控制中心，在这里可以管理用户、房间、系统设置和版本更新。</p><hr><h2 id="如何进入管理后台" tabindex="-1">如何进入管理后台 <a class="header-anchor" href="#如何进入管理后台" aria-label="Permalink to &quot;如何进入管理后台&quot;">​</a></h2><p>有两种方式可以进入：</p><ol><li><strong>首页按钮</strong>：在首页顶部导航栏或页面中，找到「<strong>权限管理</strong>」按钮，点击即可进入</li><li><strong>直接输入地址</strong>：在浏览器地址栏输入 <code>http://你的服务器地址/admin</code>（例如 <code>http://192.168.1.100:3000/admin</code>）</li></ol><blockquote><p>只有 <strong>root</strong> 和 <strong>admin</strong> 角色才能看到和进入管理后台。如果你是普通用户或游客，页面不会显示入口。</p></blockquote><h2 id="四个-tab-概览" tabindex="-1">四个 Tab 概览 <a class="header-anchor" href="#四个-tab-概览" aria-label="Permalink to &quot;四个 Tab 概览&quot;">​</a></h2><p>进入后台后，你会看到上方有四个选项卡（Tab）：</p><table tabindex="0"><thead><tr><th>Tab</th><th>说明</th><th>可用角色</th></tr></thead><tbody><tr><td><strong>用户管理</strong></td><td>管理用户注册、角色、审核</td><td>仅 root</td></tr><tr><td><strong>房间管理</strong></td><td>查看和管理所有房间</td><td>root + admin</td></tr><tr><td><strong>基础设置</strong></td><td>修改系统全局设置</td><td>仅 root</td></tr><tr><td><strong>版本更新</strong></td><td>检查和应用更新</td><td>root + admin</td></tr></tbody></table><hr><h2 id="用户管理-tab-仅-root" tabindex="-1">用户管理 Tab（仅 root） <a class="header-anchor" href="#用户管理-tab-仅-root" aria-label="Permalink to &quot;用户管理 Tab（仅 root）&quot;">​</a></h2><h3 id="注册方式设置" tabindex="-1">注册方式设置 <a class="header-anchor" href="#注册方式设置" aria-label="Permalink to &quot;注册方式设置&quot;">​</a></h3><ol><li>在「注册方式」下拉框中，选择你想要的模式： <ul><li><strong>开放注册</strong>：任何人注册后直接激活</li><li><strong>审批注册</strong>：注册后需审核</li><li><strong>禁止注册</strong>：关闭注册入口</li></ul></li><li>点击旁边的「<strong>保存</strong>」按钮，设置立即生效</li></ol><h3 id="用户列表" tabindex="-1">用户列表 <a class="header-anchor" href="#用户列表" aria-label="Permalink to &quot;用户列表&quot;">​</a></h3><p>页面会列出所有已注册的用户，显示以下信息：</p><ul><li>用户名</li><li>角色（root / admin / user / guest）</li><li>状态（active 已激活 / pending 待审核）</li><li>注册时间</li></ul><h3 id="审核用户" tabindex="-1">审核用户 <a class="header-anchor" href="#审核用户" aria-label="Permalink to &quot;审核用户&quot;">​</a></h3><p>对于状态为「待审核」的用户，操作栏中会出现「<strong>审核通过</strong>」按钮。点击后该用户升级为正式 user。</p><h3 id="修改角色" tabindex="-1">修改角色 <a class="header-anchor" href="#修改角色" aria-label="Permalink to &quot;修改角色&quot;">​</a></h3><p>点击用户操作栏中的「<strong>修改角色</strong>」，可以选择将该用户提升为 admin 或降级为 user/guest。</p><blockquote><p>注意：不能修改 root 角色的权限，也不能将最后一个 root 降级。</p></blockquote><h3 id="删除用户" tabindex="-1">删除用户 <a class="header-anchor" href="#删除用户" aria-label="Permalink to &quot;删除用户&quot;">​</a></h3><p>点击「<strong>删除</strong>」按钮可以移除该用户。此操作不可撤销，请谨慎操作。</p><hr><h2 id="房间管理-tab" tabindex="-1">房间管理 Tab <a class="header-anchor" href="#房间管理-tab" aria-label="Permalink to &quot;房间管理 Tab&quot;">​</a></h2><h3 id="房间列表" tabindex="-1">房间列表 <a class="header-anchor" href="#房间列表" aria-label="Permalink to &quot;房间列表&quot;">​</a></h3><p>这里列出了当前服务器上<strong>所有</strong>的房间，包括其他用户创建的。每条记录显示：</p><ul><li>房间名称</li><li>房主（创建者）</li><li>当前在线人数</li><li>观看模式</li></ul><h3 id="视图切换" tabindex="-1">视图切换 <a class="header-anchor" href="#视图切换" aria-label="Permalink to &quot;视图切换&quot;">​</a></h3><p>支持两种查看方式：</p><ul><li><strong>列表视图</strong>：以表格形式展示，信息更详细</li><li><strong>卡片视图</strong>：以卡片形式展示，更直观</li></ul><p>点击右上角的切换按钮即可切换。</p><h3 id="批量操作" tabindex="-1">批量操作 <a class="header-anchor" href="#批量操作" aria-label="Permalink to &quot;批量操作&quot;">​</a></h3><p>勾选多个房间左侧的复选框，然后：</p><ul><li><strong>批量删除</strong>：删除选中的房间</li><li><strong>删除所有</strong>：清空服务器上所有房间（仅 root）</li><li><strong>清理无人房间</strong>：自动删除当前没有观众的房间</li><li><strong>刷新</strong>：重新加载房间列表，获取最新数据</li></ul><blockquote><p>删除房间后，房间内的所有观众会被断开连接。</p></blockquote><hr><h2 id="基础设置-tab-仅-root" tabindex="-1">基础设置 Tab（仅 root） <a class="header-anchor" href="#基础设置-tab-仅-root" aria-label="Permalink to &quot;基础设置 Tab（仅 root）&quot;">​</a></h2><h3 id="自动清理" tabindex="-1">自动清理 <a class="header-anchor" href="#自动清理" aria-label="Permalink to &quot;自动清理&quot;">​</a></h3><p>开启后，系统会自动删除长时间无人观看的房间：</p><ul><li><strong>自动清理开关</strong>：开启/关闭此功能</li><li><strong>清理时间</strong>：设置房间无人多少小时后自动删除（例如 24 小时）</li></ul><h3 id="房间创建权限" tabindex="-1">房间创建权限 <a class="header-anchor" href="#房间创建权限" aria-label="Permalink to &quot;房间创建权限&quot;">​</a></h3><p>选择谁可以创建房间：</p><ul><li><strong>仅管理员</strong>：只有 root 和 admin 可以创建</li><li><strong>所有用户</strong>：user 也可以创建</li></ul><h3 id="beta-功能开关" tabindex="-1">Beta 功能开关 <a class="header-anchor" href="#beta-功能开关" aria-label="Permalink to &quot;Beta 功能开关&quot;">​</a></h3><p>可以开启或关闭以下实验性功能：</p><ul><li><strong>Kazumi 番剧源</strong>：Kazumi 动漫数据源</li><li><strong>AniSubs 番剧源</strong>：AniSubs 动漫数据源</li><li><strong>Bilibili 下载</strong>：B站视频下载功能</li></ul><p>开启 Beta 功能可能会影响系统稳定性，请按需使用。</p><h3 id="kazumi-规则源配置" tabindex="-1">Kazumi 规则源配置 <a class="header-anchor" href="#kazumi-规则源配置" aria-label="Permalink to &quot;Kazumi 规则源配置&quot;">​</a></h3><p>如果你使用 Kazumi 数据源，可以在这里配置规则源的 URL。修改后会清空动漫源缓存，重新拉取数据。</p><hr><h2 id="版本更新-tab" tabindex="-1">版本更新 Tab <a class="header-anchor" href="#版本更新-tab" aria-label="Permalink to &quot;版本更新 Tab&quot;">​</a></h2><h3 id="检查更新" tabindex="-1">检查更新 <a class="header-anchor" href="#检查更新" aria-label="Permalink to &quot;检查更新&quot;">​</a></h3><p>点击「<strong>检查更新</strong>」按钮，系统会自动查询 GitHub 上是否有新版本。如果有，会显示新版本的版本号和更新内容。</p><h3 id="一键更新" tabindex="-1">一键更新 <a class="header-anchor" href="#一键更新" aria-label="Permalink to &quot;一键更新&quot;">​</a></h3><p>点击「<strong>一键更新</strong>」按钮，系统会自动下载最新版本并应用更新。更新过程中服务器会短暂重启，当前正在观看的用户可能会被断开。</p><h3 id="手动导入更新包" tabindex="-1">手动导入更新包 <a class="header-anchor" href="#手动导入更新包" aria-label="Permalink to &quot;手动导入更新包&quot;">​</a></h3><p>如果服务器无法直接访问 GitHub（例如在内网环境），可以：</p><ol><li>在其他电脑上下载更新包（<code>.zip</code> 或 <code>.tar.gz</code> 格式，不超过 500MB）</li><li>在本页面点击「<strong>选择文件</strong>」</li><li>选择下载好的更新包</li><li>点击「<strong>上传并应用</strong>」</li></ol><h3 id="接收预发布版本" tabindex="-1">接收预发布版本 <a class="header-anchor" href="#接收预发布版本" aria-label="Permalink to &quot;接收预发布版本&quot;">​</a></h3><p>开启此选项后，检查更新时也会显示预发布版本（Pre-release）。预发布版本包含最新的功能，但可能不够稳定，建议仅在测试环境使用。</p><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="看不到管理后台入口" tabindex="-1">看不到管理后台入口 <a class="header-anchor" href="#看不到管理后台入口" aria-label="Permalink to &quot;看不到管理后台入口&quot;">​</a></h3><p>可能的原因：</p><ol><li>你当前登录的账号不是 <strong>root</strong> 或 <strong>admin</strong> 角色</li><li>你还没有登录，或者登录已过期</li><li>页面没有刷新——尝试刷新首页或直接访问 <code>/admin</code> 路径</li></ol><h3 id="按钮是灰色的-点不了" tabindex="-1">按钮是灰色的，点不了 <a class="header-anchor" href="#按钮是灰色的-点不了" aria-label="Permalink to &quot;按钮是灰色的，点不了&quot;">​</a></h3><ul><li>某些操作（如审核用户、修改角色）<strong>仅限 root</strong> 使用</li><li>如果你是 admin，看到灰色按钮是正常的，因为这些功能对你不可用</li></ul><h3 id="更新失败怎么办" tabindex="-1">更新失败怎么办 <a class="header-anchor" href="#更新失败怎么办" aria-label="Permalink to &quot;更新失败怎么办&quot;">​</a></h3><ol><li>检查服务器是否能够访问 GitHub（能否正常打开 <code>github.com</code>）</li><li>如果网络受限，使用「手动导入更新包」方式</li><li>查看服务器日志，确认是否有更详细的错误信息</li><li>如果一键更新反复失败，可以尝试手动下载更新包后上传</li></ol>',71)])])}const g=t(i,[["render",e]]);export{c as __pageData,g as default};
